import assert from "node:assert/strict";
import { test } from "node:test";
import { parseArgs, render } from "../src/cli.ts";

test("grader: --json flag", () => {
  assert.deepEqual(parseArgs(["a", "--json", "b"]), { json: true, words: ["a", "b"] });
  assert.deepEqual(parseArgs(["a"]), { json: false, words: ["a"] });
  assert.throws(() => parseArgs(["--nope"]), /nope/);
  assert.equal(render({ json: true, words: ["a", "b"] }), '{"words":["a","b"]}');
  assert.equal(render({ json: false, words: ["a", "b"] }), "a b");
});

