export interface Args {
  json: boolean;
  words: string[];
}

export function parseArgs(argv: string[]): Args {
  const args: Args = { json: false, words: [] };
  for (const a of argv) {
    if (a === "--json") args.json = true;
    else if (a.startsWith("--")) throw new Error(`unknown flag: ${a}`);
    else args.words.push(a);
  }
  return args;
}

export function render(args: Args): string {
  if (args.json) return JSON.stringify({ words: args.words });
  return args.words.join(" ");
}

